// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount) public {
        vm.assume(user != address(0));
        depositAmount = bound(depositAmount, 0, 1e30);

        uint256 initialBalance = address(c).balance;

        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        uint256 finalBalance = address(c).balance;

        assertTrue(finalBalance == initialBalance + depositAmount);
    }
}

