// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAfter) public {
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 0, 1e18);
        withdrawAfter = bound(withdrawAfter, 0, 10);

        // Perform a deposit from a different user to ensure credit[caller] could be zero
        vm.deal(address(0xdead), depositAmount);
        vm.prank(address(0xdead));
        c.deposit{value: depositAmount}();

        // Now caller has zero credit (never deposited)
        uint256 balanceBefore = address(caller).balance;

        vm.prank(caller);
        c.withdrawAll();

        uint256 balanceAfter = address(caller).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
